return ['.br-skiplink','.br-skiplink a','.barra-superior','.marca-govbr','.br-list','#documentos','.upload-button','.upload-label','#data-preferencial-btn','.flatpickr-calendar','.retorno-envio','#cpf-apoio','#data-apoio','#descricao-apoio','#documentos-apoio','.apoio-solicitacao','label[for=nome]','#nome','#cpf','#servico','.table-title','.page.active','.page','th','td','.acao-enviar','.acao-cancelar','.grupo-forma legend','#forma-presencial','#forma-presencial + label','.crumb a','.crumb span', '.titulo-solicitacao','h2'].flatMap(s=>q(s).slice(0,2).map(e=>({s, ...info(e)})));
}"}

